  FROM motor_corrida c
 WHERE c.semestre_id = 2 AND c.departamentos = '3'
   AND c.subido_at BETWEEN '2026-10-29 17:28:00' AND '2026-10-29 17:28:59';

-- Debe dar 12 subidas con versiones: 2 cada una de DACE (Matemáticas y Estadística; Actuaría no
-- tiene grupos sin publicar, todo lo suyo está publicado) y 1 cada una de Estadística. 22 filas.
SELECT c.id AS corrida_id, c.subido_at, c.departamentos, COUNT(v.id) AS versiones
  FROM motor_corrida c LEFT JOIN malla_version v ON v.corrida_id = c.id
 WHERE c.subido_at < '2026-10-29 18:00:00'
 GROUP BY c.id, c.subido_at, c.departamentos
 ORDER BY c.id;
